// Middleware customizado de log de auditoria
function logRequisicao(req, res, next) {
  const inicio = Date.now();
  res.on('finish', () => {
    const duracao = Date.now() - inicio;
    console.log(`[${req.method}] ${req.url} - Status: ${res.statusCode} (${duracao}ms)`);
  });
  next(); // Passa o controle para o próximo da fila
}

