// Middleware autorizador baseado em permissões (RBAC)
function autorizar(...papeisPermitidos) {
  return (req, res, next) => {
    if (!req.usuario || !papeisPermitidos.includes(req.usuario.role)) {
      return res.status(403).json({ erro: 'Acesso negado: privilégios insuficientes' });
    }
    next();
  };
}
